    /**
     * Returns a <span aria-hidden> wrapping the named SVG icon.
     * Returns empty string if the icon name is not registered.
     *
     * @param string $name  Icon key (e.g. 'check-circle')
     * @param string $class Additional CSS classes for the wrapper span
     */
    public static function get(string $name, string $class = ''): string
    {
        $svg = self::ICONS[$name] ?? '';
        if ($svg === '')
        {
            return '';
        }

        $cls = 'eggb-icon';
        if ($class !== '')
        {
            $cls .= ' ' . $class;
        }

        return '<span class="' . esc_attr($cls) . '" aria-hidden="true">' . $svg . '</span>';
    }

    /**
     * Returns all registered icon names.
     * Use this to populate a user-facing icon selector in the future.
     *
     * @return string[]
     */
    public static function names(): array
    {
        return array_keys(self::ICONS);
    }
}
